/// `melee_modes::tu::ext_hook::EXT_FALLBACK`: the by-name `ext_fns!` callees answered "feature off".
pub unsafe fn ext_fallback(name: &str, args: &[u64]) -> u64 {
    if let Some(v) = crate::seams::ext_real(name, args) {
        return v;
    }
    match name {
        "GXBegin" | "GXClearVtxDesc" | "GXColor4u8" | "GXFlush" | "GXLoadPosMtxImm" | "GXPosition1x8" => 0x0,
        "GXPosition3f32" | "GXSetArray" | "GXSetCullMode" | "GXSetCurrentMtx" | "GXSetNumTevStages" | "GXSetTevAlphaIn" => 0x0,
        "GXSetTevAlphaOp" | "GXSetTevColor" | "GXSetTevColorIn" | "GXSetTevColorOp" | "GXSetTevKColor" | "GXSetTevKColorSel" => 0x0,
        "GXSetTevOrder" | "GXSetTevSwapMode" | "GXSetVtxAttrFmt" | "GXSetVtxDesc" | "GXSetZMode" | "Geno_CommonMoveTag" => 0x0,
        "Geno_DefineIsNone" | "Geno_DefinePlanInt" | "Geno_OverlayAnim" | "Geno_OverlayCount" | "Geno_OverlayMoveTag" | "Geno_StateMoveTag" => 0x0,
        "HeapCheckFull" | "Mex_Enabled" | "Mex_GrFile" | "Mex_GrKindForExt" | "Mex_ItemCustomDesc" | "Mex_ItemReady" => 0x0,
        "Mex_ResultScaleForPortCKind" | "Mex_SssIconCount" | "Mex_SssTable" | "Netplay_Enabled" | "OSCheckHeap" | "OSReport" => 0x0,
        "ProfActive" | "ProfBegin" | "ProfEnd" | "RB_Enabled" | "Replay_Active" | "Script_AreaNameByte" => 0x0,
        "Script_ArmorEvent" | "Script_BossHookEnabled" | "Script_CpuIdleDefault" | "Script_CritEvent" | "Script_EchoInput" | "Script_EchoOwnerAlive" => 0x0,
        "Script_EnemyDefeated" | "Script_EnemyGameEvent" | "Script_EnemyHit" | "Script_EnemyRemoved" | "Script_GameEvent" | "Script_HitContext" => 0x0,
        "Script_HitOriginalElement" | "Script_HitRuleContext" | "Script_HitRulesInput" | "Script_ModelDraw" | "Script_ModelInput" | "Script_NetModsVariant" => 0x0,
        "Script_OnePClear" | "Script_OnePComplete" | "Script_OnePGameOver" | "Script_OnePOffline" | "Script_OnePScripted" | "Script_OnePSpawn" => 0x0,
        "Script_OnePStage" | "Script_SimByte" | "Script_SkillEvent" | "Script_StageArchiveInput" | "Script_StageIsolationAllowed" | "Script_StageIsolationReleased" => 0x0,
        "Script_StageModelDraw" | "Script_StageModelFor" | "Script_StageModelsReset" | "Script_StageRawStash" | "Script_StageResourceOwner" | "Script_StageResourceOwnerAlive" => 0x0,
        "Script_StageSlotMissionInput" | "Script_StageSlotVisual" | "Script_StageSlotsEnded" | "Script_StageTextByte" | "Script_StageWanted" | "Script_TargetBroken" => 0x0,
        "Script_WarmModelDraw" | "Script_WarmSync" | "Wb_RenderActive" | "Wb_RenderOption" => 0x0,
        "Geno_DefineBaseKind" | "Geno_ProfileForKind" => 0xffffffffffffffff,
        _ => panic!("TODO ext: {name} is in a TU that is not ported yet"),
    }
}

